import io, urllib.error
class Resp(io.BytesIO):
    def __enter__(self): return self
    def __exit__(self, *a): return False
from fetchit import fetch_json, FetchError
try:
    fetch_json('http://x.invalid/', require=['id'], opener=lambda req, timeout: Resp(b'{"name": 1}'))
    raise SystemExit('no error')
except FetchError:
    pass
assert fetch_json('http://x.invalid/', require=['id'], opener=lambda req, timeout: Resp(b'{"id": 1}')) == {'id': 1}
